 1→import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
 2→import { GameState, GameStateService } from '../game-state.service';
 3→import { ProgressionService } from '../progression.service';
 4→import { NoteDataService } from '../note-data.service';
 5→import { FretboardDisplayComponent } from '../fretboard-display/fretboard-display';
