 7→@Component({
 8→  selector: 'app-fretboard-flash-page',
 9→  templateUrl: './fretboard-flash-page.html',
10→  styleUrl: './fretboard-flash-page.scss',
11→  changeDetection: ChangeDetectionStrategy.OnPush,
12→  imports: [FretboardDisplayComponent],
13→  providers: [GameStateService, ProgressionService, NoteDataService],
14→})
15→export class FretboardFlashPageComponent {
16→  private readonly gameState = inject(GameStateService);
17→
18→  readonly state = this.gameState.state;
19→  readonly currentNote = this.gameState.currentNote;
20→  readonly isIdle = computed(() => this.state() === GameState.IDLE);
21→  readonly isShowAnswer = computed(() => this.state() === GameState.SHOW_ANSWER);
22→  readonly fretboardNote = computed(() => this.isShowAnswer() ? this.currentNote() : null);
23→
24→  start(): void {
25→    this.gameState.start();
26→  }
27→
28→  stop(): void {
29→    this.gameState.stop();
30→  }
31→}
