input.new_string:
// Width is set as a percentage of the overlay container width via inline style.
// aspect-ratio: 1 derives the height from that width, keeping the dot circular
// and proportionally scaled at any screen size.
.note-marker {
  position: absolute;
  aspect-ratio: 1;
  border-radius: 50%;
  background-color: var(--gt-accent);
  transform: translate(-50%, -50%);
  pointer-events: none;
  border: 2px solid rgba(255, 255, 255, 0.9);
  box-shadow: var(--gt-marker-glow);
  animation: note-marker-appear 0.35s ease-out both;
}

@keyframes note-marker-appear {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0);
  }

  70% {
    transform: translate(-50%, -50%) scale(1.15);
  }

  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

