105→// CTA section
106→// Note: The CTA button uses custom styling instead of Taiga UI's tuiButton directive
107→// because the design spec requires a shine-effect on hover (pseudo-element animation),
108→// which is not achievable through Taiga UI's button API. This is a deliberate deviation.
109→.cta {
110→  background: var(--gt-surface);
111→  text-align: center;
112→  padding: gt.$section-padding;
113→  animation: fadeInUp 0.6s ease-out both;
114→  animation-delay: 0.5s;
115→
116→  &__button {
117→    display: inline-block;
118→    position: relative;
119→    overflow: hidden;
120→    font-size: 1.15rem;
121→    padding: 0.85rem 2.5rem;
122→    border-radius: gt.$border-radius;
123→    background: linear-gradient(135deg, gt.$accent-orange, gt.$accent-orange-light);
124→    color: gt.$neutral-white;
125→    font-weight: 700;
126→    border: none;
127→    cursor: pointer;
128→    text-decoration: none;
129→    transition:
130→      transform gt.$transition-base,
131→      box-shadow gt.$transition-base;
132→
133→    // Shine effect on hover — uses transform instead of left for compositor-only animation
134→    &::after {
135→      content: '';
136→      position: absolute;
137→      top: -50%;
138→      left: 0;
139→      width: 50%;
140→      height: 200%;
141→      background: linear-gradient(
142→        90deg,
143→        transparent,
144→        rgba(255, 255, 255, 0.3),
145→        transparent
146→      );
147→      transform: translateX(-150%) skewX(-25deg);
148→      transition: transform 0.6s ease;
149→    }
150→
151→    &:hover {
152→      transform: translateY(-2px);
153→      box-shadow: 0 4px 20px rgba(253, 141, 50, 0.4);
154→
155→      &::after {
156→        transform: translateX(250%) skewX(-25deg);
157→      }
158→    }
159→
160→    &:active {
161→      transform: translateY(0);
162→    }
163→  }
164→}
165→
166→// Responsive
167→@media (max-width: 768px) {
