227→          if (rule.cssText.includes('note-marker')) {
228→            rules.push(rule.cssText);
229→          }
230→        }
231→      } catch {
232→        // cross-origin sheets may throw
233→      }
234→    }
235→    return rules.join(' ');
236→  }
237→
238→  function collectAllCssRules(): string {
239→    const styleSheets = Array.from(nativeElement.ownerDocument.styleSheets);
240→    const rules: string[] = [];
